.toolbar{display:flex;align-items:center;justify-content:center}.toolbar-cluster{display:flex;align-items:center;gap:3px}.toolbar-group{display:flex;align-items:center;gap:1px}.group-divider{width:1px;height:22px;background:var(--line);margin:0 7px}.icon-button{width:42px;height:42px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;color:var(--muted);background:transparent;border:0;transition:background .2s,color .2s,transform .2s}.icon-button:hover{color:var(--ink);background:var(--accent-soft)}.icon-button:active{transform:scale(.93)}.icon-button.active{color:var(--accent)}.collection-phone{display:none}@media(max-width:740px){.toolbar-cluster{gap:0}.icon-button{width:40px;height:40px}.group-divider{margin:0 2px;height:18px}.collection-phone{display:inline-flex}.fullscreen{display:none}}@media(max-width:380px){.icon-button{width:37px;height:40px}.group-divider{display:none}}
